export const AI_ANALYSIS_STATUS = {

  REQUESTED: 'REQUESTED',

  COMPLETED: 'COMPLETED',

  FAILED: 'FAILED',

  VALIDATION_FAILED: 'VALIDATION_FAILED',

};



export const AI_REVIEW_STATUS = {

  AI_DRAFT: 'AI_DRAFT',

  HUMAN_REVIEW_REQUIRED: 'HUMAN_REVIEW_REQUIRED',

  PARTIALLY_ACCEPTED: 'PARTIALLY_ACCEPTED',

  ACCEPTED: 'ACCEPTED',

  REJECTED: 'REJECTED',

  SUPERSEDED: 'SUPERSEDED',

};



export const AI_FRESHNESS = {

  CURRENT: 'CURRENT',

  OUTDATED: 'OUTDATED',

};



export const AI_ANALYSIS_ERROR_CODES = {

  INCOMPLETE: 'INCOMPLETE',

  REFUSAL: 'REFUSAL',

  TIMEOUT: 'TIMEOUT',

  RATE_LIMITED: 'RATE_LIMITED',

  AUTH_ERROR: 'AUTH_ERROR',

  PROVIDER_ERROR: 'PROVIDER_ERROR',

  CONTEXT_HASH_MISMATCH: 'CONTEXT_HASH_MISMATCH',

  UNSUPPORTED_DATE_CLAIM: 'UNSUPPORTED_DATE_CLAIM',

  UNSAFE_AI_CACHE_PATH: 'UNSAFE_AI_CACHE_PATH',

  ORIGIN_NOT_ALLOWED: 'ORIGIN_NOT_ALLOWED',

  STORAGE_QUOTA_EXCEEDED: 'STORAGE_QUOTA_EXCEEDED',

};



const ERROR_TO_STATUS = {

  [AI_ANALYSIS_ERROR_CODES.INCOMPLETE]: AI_ANALYSIS_STATUS.FAILED,

  [AI_ANALYSIS_ERROR_CODES.REFUSAL]: AI_ANALYSIS_STATUS.FAILED,

  [AI_ANALYSIS_ERROR_CODES.TIMEOUT]: AI_ANALYSIS_STATUS.FAILED,

  [AI_ANALYSIS_ERROR_CODES.RATE_LIMITED]: AI_ANALYSIS_STATUS.FAILED,

  [AI_ANALYSIS_ERROR_CODES.AUTH_ERROR]: AI_ANALYSIS_STATUS.FAILED,

  [AI_ANALYSIS_ERROR_CODES.PROVIDER_ERROR]: AI_ANALYSIS_STATUS.FAILED,

  [AI_ANALYSIS_ERROR_CODES.CONTEXT_HASH_MISMATCH]: AI_ANALYSIS_STATUS.VALIDATION_FAILED,

  [AI_ANALYSIS_ERROR_CODES.UNSUPPORTED_DATE_CLAIM]: AI_ANALYSIS_STATUS.VALIDATION_FAILED,

};



export function statusForAnalysisErrorCode(errorCode) {

  return ERROR_TO_STATUS[errorCode] || null;

}



export function isAllowedAnalysisStatus(status) {

  return Object.values(AI_ANALYSIS_STATUS).includes(status);

}



